    The string consists solely of '[' and ']'.
    """
    n = len(string)
    if n < 4:
        return False

    # Precompute whether a closing bracket exists to the right of each position.
    suffix_has_close = [False] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_has_close[i] = suffix_has_close[i + 1] or (string[i] == ']')

    open_count = 0
    for j, ch in enumerate(string):
        if ch == '[':
            open_count += 1
        elif ch == ']':
            if open_count >= 2 and suffix_has_close[j + 1]:
                return True
    return False

