import functools

def tri(n: int) -> list[int]:
    """Return the first n + 1 Tribonacci numbers (tri(0) … tri(n))."""
    if n < 0:
        raise ValueError("n must be non‑negative")

    @functools.lru_cache(maxsize=None)
    def _tri(k: int) -> int:
        if k == 0:
            return 1
        if k == 1:
            return 3
        if k % 2 == 0:
            # even n: 1 + n/2
            return 1 + k // 2
        # odd n: tri(n-1) + tri(n-2) + tri(n+1)
        return _tri(k - 1) + _tri(k - 2) + _tri(k + 1)

    return [_tri(i) for i in range(n + 1)]

