def split_words(txt):
    """
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order
    in the alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    """
    # If there is any whitespace character, split on whitespace
    if any(c.isspace() for c in txt):
        return txt.split()

    # If there are commas, split on commas
    if ',' in txt:
        return txt.split(',')

    # Otherwise, count lower-case letters with odd alphabetical index
    base = ord('a')
    return sum(
