        if c.islower() and ((ord(c) - base) % 2 == 1)
    )

def make_palindrome(string: str) -> str:
    """Find the shortest palindrome that begins with the supplied string."""
    # Find the earliest index i such that the suffix string[i:] is a palindrome.
    for i in range(len(string) + 1):
        if is_palindrome(string[i:]):
            # Append the reverse of the prefix before the palindromic suffix.
            return string + string[:i][::-1]
    # In practice the loop will always return; this line is just a safety net.
    return string

