def encrypt(s: str) -> str:
    """Encrypt a string by shifting each alphabetic character forward by 4 positions,
    wrapping around the alphabet. Non‑alphabetic characters are left unchanged.

    The shift value is 4, which corresponds to "two multiplied to two" as described.
    """
    result = []
    shift = 4
    for ch in s:
        if 'a' <= ch <= 'z':
            new_ord = ord('a') + (ord(ch) - ord('a') + shift) % 26
            result.append(chr(new_ord))
        elif 'A' <= ch <= 'Z':
            new_ord = ord('A') + (ord(ch) - ord('A') + shift) % 26
            result.append(chr(new_ord))
        else:
            result.append(ch)
    return ''.join(result)

def is_sorted(lst):
    '''
    Given a list of numbers, return whether or not they are sorted
    in ascending order. If list has more than 1 duplicate of the same
    number, return False. Assume no negative numbers and only integers.
    '''
    counts = {}
    prev = None
    for num in lst:
        if prev is not None and num < prev:
            return False
        prev = num
        counts[num] = counts.get(num, 0) + 1
        if counts[num] > 2:
            return False
    return True

