def change_base(x: int, base: int) -> str:
    """Change numerical base of input number x to the given base (base < 10).

    Returns the string representation of ``x`` in the new base.
    Supports non‑negative integers; ``0`` returns ``'0'``.
    """
    if base < 2 or base > 9:
        raise ValueError("base must be between 2 and 9 inclusive")
    if x < 0:
        raise ValueError("negative numbers are not supported")
    if x == 0:
        return "0"

    digits = []
    while x:
