def correct_bracketing(brackets: str) -> bool:
    """
    Return True if every opening bracket has a corresponding closing bracket.
    """
    balance = 0
    for ch in brackets:
        if ch == '(':
            balance += 1
        elif ch == ')':
            balance -= 1
            if balance < 0:  # a closing bracket without a matching opening
                return False
        else:
            # ignore any characters that are not parentheses
            continue
    return balance == 0

from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Split the string into individual letters, ignoring extra whitespace.
    letters = test.split()
    if not letters:
        return {}

    # Count occurrences of each letter.
    counts = Counter(letters)

    # Determine the maximum count.
    max_count = max(counts.values())

    # Build the result dictionary with only those letters that match the max count.
    return {letter: max_count for letter, cnt in counts.items() if cnt == max_count}

def minPath(grid, k):
    """
    Return the lexicographically smallest sequence of cell values that
    can be obtained by visiting exactly k cells in the grid, moving only
    between edge‑adjacent cells.  The answer is guaranteed to be unique.
    """
    N = len(grid)
    # sequences for path length 1 (just the cell value)
    dp_prev = [[ [grid[i][j]] for j in range(N)] for i in range(N)]

    if k == 1:
        # minimal cell value (grid contains 1..N*N)
        min_val = min(grid[i][j] for i in range(N) for j in range(N))
        return [min_val]

    # Build DP for path lengths 2..k
    for step in range(2, k + 1):
        dp_curr = [[None] * N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                best_seq = None
                # explore 4‑neighbour cells
                for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < N and 0 <= nj < N:
                        candidate = [grid[i][j]] + dp_prev[ni][nj]
                        if best_seq is None or candidate < best_seq:
                            best_seq = candidate
                dp_curr[i][j] = best_seq
        dp_prev = dp_curr

    # Choose the globally smallest sequence among all starting cells
    min_seq = None
    for i in range(N):
        for j in range(N):
            seq = dp_prev[i][j]
            if min_seq is None or seq < min_seq:
                min_seq = seq

    return min_seq

