def compare_one(a, b):
    """
    Returns the larger of two values (int, float, or numeric strings) preserving
    the original type of the larger value. If the numeric values are equal,
    returns None.

    Numeric strings may use '.' or ',' as a decimal separator.
    """
    def to_float(val):
        if isinstance(val, (int, float)):
            return float(val)
        if isinstance(val, str):
            # Replace comma with dot for decimal separator and strip whitespace
            try:
                return float(val.replace(',', '.').strip())
            except ValueError:
                raise ValueError(f"Invalid numeric string: {val!r}")
        raise TypeError(f"Unsupported type: {type(val)}")

    num_a = to_float(a)
    num_b = to_float(b)

    if num_a > num_b:
        return a
    if num_b > num_a:
        return b
    return None
